package config

import (
	"strings"
	"testing"
)

// serve must boot with DATABASE_URL alone (JWT_SECRET is generated by the app
// before Load); everything else has a neutral default.
func TestLoadWithOnlyDatabaseURL(t *testing.T) {
	for _, k := range []string{"SMTP_FROM", "SMTP_FROM_NAME", "HATAMOTO_CANONICAL_SLUG", "HATAMOTO_SITE_NAME", "SMTP_HOST", "ENVIRONMENT"} {
		t.Setenv(k, "")
	}
	t.Setenv("DATABASE_URL", "postgres://u:p@localhost:5432/db")
	t.Setenv("JWT_SECRET", "0123456789abcdef0123456789abcdef") // gitleaks:allow (test value)
	cfg, err := Load()
	if err != nil {
		t.Fatal(err)
	}
	if err := cfg.Validate(); err != nil {
		t.Fatalf("a DATABASE_URL-only configuration must validate: %v", err)
	}
	if cfg.SMTP.From != DefaultSMTPFrom || cfg.Hatamoto.CanonicalSlug != DefaultCanonicalSlug || cfg.Hatamoto.SiteName != DefaultSiteName {
		t.Errorf("defaults not applied: %+v %+v", cfg.SMTP, cfg.Hatamoto)
	}
	if cfg.SMTP.FromName != DefaultSiteName {
		t.Errorf("sender name should follow the site name, got %q", cfg.SMTP.FromName)
	}
	if cfg.SMTP.Host != "localhost" {
		t.Errorf("email must stay unconfigured by default, SMTP host %q", cfg.SMTP.Host)
	}
}

func TestExplicitIdentityBeatsDefaults(t *testing.T) {
	t.Setenv("DATABASE_URL", "postgres://u:p@localhost:5432/db")
	t.Setenv("JWT_SECRET", "0123456789abcdef0123456789abcdef") // gitleaks:allow (test value)
	t.Setenv("SMTP_FROM", "hello@acme.test")
	t.Setenv("SMTP_FROM_NAME", "Acme Mail")
	t.Setenv("HATAMOTO_CANONICAL_SLUG", "acme")
	t.Setenv("HATAMOTO_SITE_NAME", "Acme")
	cfg, err := Load()
	if err != nil {
		t.Fatal(err)
	}
	if cfg.SMTP.From != "hello@acme.test" || cfg.SMTP.FromName != "Acme Mail" || cfg.Hatamoto.CanonicalSlug != "acme" || cfg.Hatamoto.SiteName != "Acme" {
		t.Errorf("explicit values lost: %+v %+v", cfg.SMTP, cfg.Hatamoto)
	}
}

func TestValidateStillRequiresDatabaseAndSecret(t *testing.T) {
	t.Setenv("DATABASE_URL", "")
	t.Setenv("JWT_SECRET", "0123456789abcdef0123456789abcdef") // gitleaks:allow (test value)
	cfg, _ := Load()
	if cfg.Validate() == nil {
		t.Error("DATABASE_URL must stay required")
	}
	t.Setenv("DATABASE_URL", "postgres://x")
	t.Setenv("JWT_SECRET", "short")
	cfg, _ = Load()
	if cfg.Validate() == nil {
		t.Error("a short JWT_SECRET must be refused")
	}
}

func TestSMTPHostRequiresAnExplicitSender(t *testing.T) {
	t.Setenv("DATABASE_URL", "postgres://u:p@localhost:5432/db")
	t.Setenv("JWT_SECRET", "0123456789abcdef0123456789abcdef") // gitleaks:allow (test value)
	t.Setenv("SMTP_FROM", "")
	t.Setenv("SMTP_HOST", "smtp.example.com")
	cfg, _ := Load()
	if err := cfg.Validate(); err == nil || !strings.Contains(err.Error(), "SMTP_FROM") {
		t.Fatalf("SMTP_HOST without SMTP_FROM must be refused, got %v", err)
	}
	t.Setenv("SMTP_FROM", "hello@acme.test")
	cfg, _ = Load()
	if err := cfg.Validate(); err != nil {
		t.Fatal(err)
	}
	if !cfg.SMTP.FromNameFromSite {
		t.Error("an unset SMTP_FROM_NAME should follow the site name")
	}
	t.Setenv("SMTP_FROM_NAME", "Acme Mail")
	cfg, _ = Load()
	if cfg.SMTP.FromNameFromSite {
		t.Error("an explicit SMTP_FROM_NAME must stay")
	}
}

// HATAMOTO_SECRET is the preferred name; JWT_SECRET keeps working for existing deployments.
func TestSecretNames(t *testing.T) {
	t.Setenv("DATABASE_URL", "postgres://u:p@localhost:5432/db")
	for _, c := range []struct{ new, old, want string }{
		{"", "old-name-0123456789abcdef0123456789", "old-name-0123456789abcdef0123456789"},
		{"new-name-0123456789abcdef0123456789", "", "new-name-0123456789abcdef0123456789"},
		{"new-name-0123456789abcdef0123456789", "old-name-0123456789abcdef0123456789", "new-name-0123456789abcdef0123456789"},
	} {
		t.Setenv("HATAMOTO_SECRET", c.new)
		t.Setenv("JWT_SECRET", c.old)
		cfg, err := Load()
		if err != nil {
			t.Fatal(err)
		}
		if cfg.Secret != c.want || cfg.Validate() != nil {
			t.Errorf("new=%q old=%q: secret %q, validate %v", c.new, c.old, cfg.Secret, cfg.Validate())
		}
	}
}
